cd /workspace && python3 - <<'EOF'
import re,ast,json
raw=open('results/grpo_gsm8k/train.log',errors='replace').read()
ansi=re.compile(r'\x1b\[[0-9;]*m')
lines=[]
for ln in raw.split('\n'):
    ln=ansi.sub('',ln)
    m=re.match(r'\(TaskRunner pid=\d+\) (.*)$', ln)
    if m: lines.append(m.group(1))
    elif ln.startswith("{'actor_rollout_ref'"): lines.append(ln)
txt='\n'.join(lines)
start=txt.index("{'actor_rollout_ref'")
depth=0
for i,ch in enumerate(txt[start:], start):
    if ch=='{': depth+=1
    elif ch=='}':
