cd /workspace/results/grpo_gsm8k && /opt/venv/bin/python -I - <<'EOF'
import re,ast
lines=open('train.log','rb').read().decode('utf-8','replace').split('\n')
pat=re.compile(r'^\x1b\[36m\(TaskRunner pid=\d+\)\x1b\[0m (.*)$|^\(TaskRunner pid=\d+\) (.*)$')
out=[]
started=False
for i,l in enumerate(lines):
    m=pat.match(l)
    if not m: 
        continue
    s=m.group(1) if m.group(1) is not None else m.group(2)
    if not started:
        if s.startswith("{'actor_rollout_ref'"):
            started=True
        else:
            continue
    out.append((i+1,s))
txt='\n'.join(s for _,s in out)
print('lines',len(out),'first line',out[0][0],'last line',out[-1][0])
try:
    d=ast.literal_eval(txt)
    print('PARSED OK keys',list(d.keys()))
except Exception as e:
    print('ERR',e)
    # find offending line using compile
    for n in range(1,len(out)+1):
        try:
            ast.literal_eval('\n'.join(s for _,s in out[:n]))
        except SyntaxError as ee:
            continue
        except ValueError:
            continue
    print('tail:',[s for _,s in out[-3:]])
EOF

